public class FINDJOINTINDEX {
/** Find the array index for a given joint ID. */

  public int findJointIndex(int id)
  {
    int min = 0, max = joint.length-1, current = (min+max)>>1;

    if (joint.length == 0)
      return -1;
    while (true)
      {
        if (joint[current].id == id)
          return current;
        if (joint[current].id > id)
          max = current-1;
        else
          min = current+1;
        if (min >= max)
          {
            if (min < joint.length && joint[min].id == id)
              return min;
            return -1;
          }
        current = (min+max)>>1;
      }
  }
}

public class MOVETIMEPOINT {
/** Move a timepoint to a different time, and return its new index in the list. */

  public int moveTimepoint(int which, double t)
  {
    Keyframe tempv;
    Smoothness temps;
    int newpos;

    for (newpos = 0; newpos < time.length && time[newpos] < t; newpos++);
    tempv = value[which];
    temps = smoothness[which];
    if (newpos > which)
      {
        newpos--;
        for (int i = which; i < newpos; i++)
          {
            value[i] = value[i+1];
            time[i] = time[i+1];
            smoothness[i] = smoothness[i+1];
          }
      }
    else
      for (int i = which; i > newpos; i--)
        {
          value[i] = value[i-1];
          time[i] = time[i-1];
          smoothness[i] = smoothness[i-1];
        }
    value[newpos] = tempv;
    time[newpos] = t;
    smoothness[newpos] = temps;
    return newpos;
  }
}

