  }
}

public class FLOOR {
/** A faster replacement for Math.floor(). */

  private static int floor(double d)
  {
    if (d < 0.0)
    {
      int f = (int) d;
      if (f != d)
        f -= 1;
      return f;
    }
    return (int) d;
  }
}

public class FLOOR {
/**
   * This method produces identical results to Math.floor() for all normal input values
   * (one which fall inside the allowed range of the int type).
   */

  public static int floor(double d)
  {
    if (d < 0.0)
    {
      int f = (int) d;
      if (f != d)
        f -= 1;
      return f;
    }
    return (int) d;
  }
}

public class CEIL {
/**
   * This method produces identical results to Math.ceil() for all normal input values
   * (one which fall inside the allowed range of the int type).
   */

  public static int ceil(double d)
  {
    if (d > 0.0)
    {
      int f = (int) d;
      if (f != d)
        f += 1;
      return f;
    }
    return ((int) d);
  }
}

public class ROUND {
/**
   * This method produces identical results to Math.round() for all normal input values
   * (one which fall inside the allowed range of the int type).
   */

  public static int round(double d)
  {
    return floor(d+0.5);
  }
}

public class POW {
/**
   * This method produces results which are nearly identical to Math.pow(), although the
   * last few digits may be different due to numerical error.  Unlike Math.pow(), this
   * method requires the exponent to be an integer.
   */

  public static double pow(double base, int exponent)
  {
    if (exponent < 0)
    {
      exponent = -exponent;
      base = 1.0/base;
    }
    double result = 1.0;
    while (exponent != 0)
    {
      if ((exponent&1) == 1)
        result *= base;
      base *= base;
      exponent = exponent>>1;
    }
    return result;
  }
}

public class ATAN {
/**
   * This method calculates a fast approximation to the arctan function.  It differs from
   * the true value by no more than 0.005 for any input value.
   * <p>
   * I found this formula on an internet discussion board post by Ranko Bojanic.  The reference
   * cited in that post was
   * <p>
   * Approximation Theory (C. Hastings, Jr., Note 143, Math. Tables Aids. Comp 6, 68 (1953))
   */

  public static double atan(double d)
  {
    if (d >= 1.0)
      return (0.5*Math.PI-d/(d*d+0.28));
    if (d <= -1.0)
      return (-0.5*Math.PI-d/(d*d+0.28));
    return (d/(1.0+0.28*d*d));
  }
}

public class NEXT {
/**
   * This is overridden to update the seed in a much faster (but not threadsafe) way.
   */

  protected int next(int bits)
  {
    currentSeed = (currentSeed*MULTIPLIER+ADDEND)&MASK;
    return (int) (currentSeed >>> (48-bits));
  }
}

public class VALUE {
/** Given a point in 3D space, return the value of the scalar noise 
      function at that point. */

  public static double value(double x, double y, double z)
  {
    return generator.getValue(x, y, z);
  }
}

public class VALUE {
/** Given a point in 3D space, return the value of the scalar noise
      function at that point. */

  public static double value(double x, double y, double z)
  {
    double xi = FastMath.floor(x), yi = FastMath.floor(y), zi = FastMath.floor(z);
    double u1 = x-xi, v1 = y-yi, w1 = z-zi;
    double u2 = 1.0-u1, v2 = 1.0-v1, w2 = 1.0-w1;
    int i = ((int) xi)&0xFF, j = ((int) yi)&0xFF, k = ((int) zi)&0xFF;

    return GRAD_SCALE*(getWavelet(i, j, k, u1, v1, w1) +
        getWavelet(i+1, j, k, u2, v1, w1) +
        getWavelet(i, j+1, k, u1, v2, w1) +
        getWavelet(i+1, j+1, k, u2, v2, w1) +
        getWavelet(i, j, k+1, u1, v1, w2) +
        getWavelet(i+1, j, k+1, u2, v1, w2) +
        getWavelet(i, j+1, k+1, u1, v2, w2) +
        getWavelet(i+1, j+1, k+1, u2, v2, w2));
  }
}

public class GETAVERAGEVALUE {
/** Calculate the average value of an output. */

  public double getAverageValue(int which, double blur)
  {
    if (!valueOk[which] || blur != lastBlur)
      calcValues(which, blur);
    if (which > 0)
      return value[which-1];
    double diff = value[1]-value[0];
    if (diff >= error)
      return cell;
    random.setSeed(id[1]);
    random.nextDouble();
    double cell2 = random.nextDouble();
    double weight = 0.5+0.5*diff/error;
    return weight*cell+(1.0-weight)*cell2;
  }
}

public class GETVALUEERROR {
/** Calculate the error of an output. */

  public double getValueError(int which, double blur)
  {
    if (!valueOk[which] || blur != lastBlur)
      calcValues(which, blur);
    if (which == 0)
      {
        double diff = value[1]-value[0];
        if (diff >= error)
          return 0.0;
        random.setSeed(id[1]);
        random.nextDouble();
        double cell2 = random.nextDouble();
        return 0.5*Math.abs(cell-cell2);
      }
    return error;
  }
}

public class GETAVERAGEVALUE {
/** Get the value of one of the components. */

  public double getAverageValue(int which, double blur)
  {
    int component = which-1;
    if (component > maxComponent)
    {
      if (component == 3)
        return 0.0;
      component = 0;
    }
    if (valueOk[component] && blur == lastBlur)
      return componentValue[component];
    if (map == null)
      return 0.0;
    if (!pointOk || blur != lastBlur)
      findPoint(blur);
    if (outside)
      return 0.0;
    if (colorModel == RGB_MODEL || component == 3)
    {
      valueOk[component] = true;
      componentValue[component] = map.getComponent(component, wrapx, wrapy, x, y, xsize, ysize);
    }
    else
    {
      colorOk = true;
      valueOk[0] = valueOk[1] = valueOk[2] = true;
      lastBlur = blur;
      map.getColor(color, wrapx, wrapy, x, y, xsize, ysize);
      float components[] = (colorModel == HSV_MODEL ? color.getHSV() : color.getHLS());
      componentValue[0] = components[0]/360.0;
      componentValue[1] = components[1];
      componentValue[2] = components[2];
    }
    return componentValue[component];
  }
}

