/**
    * Update average and return average-so-far.
    */
   public double update(final double newValue) {
      data[pos] = newValue;
      pos++;
      if (pos == periods) pos = 0;
      return calculateAve();
   }
}

public class UPDATE {
/**
    * Update average and return average-so-far.
    */
   public double update(final double newValue) {
      data[pos++%periods] = newValue;
      if ( pos==Integer.MAX_VALUE){
    	  pos = pos%periods;
      }
      return calculateAve();
   }
}

public class UPDATE {
/**
    * Update average and return average-so-far.
    */
   public double update(final double newValue) {
      sum += newValue;
      count++;
      return sum / count;
   }
}

public class INCVALUE {
/**
		 * returns the value BEFORE increment
		 */

	protected int
	incValue(
		int		index )
	{
		int	original_value = getValue( index );

		if ( original_value >= 1 ){

			return( 1 );
		}

		setValue( index, (byte)(original_value+1) );

		return( original_value );
	}
}

public class DECVALUE {
/**
		 * returns the value BEFORE decrement
		 */

	protected int
	decValue(
		int		index )
	{
		int	original_value = getValue( index );

		if ( original_value <= 0 ){

			return( 0 );
		}

		setValue( index, (byte)(original_value-1) );

		return( original_value );
	}
}

public class READBYTES {
/**
		 * Rate handling 
		 */

	public int
	readBytes(
		int		max )
	{
			// permission to read a bunch of bytes

			// we're out of step here due to multiple threads so we have to report what
			// has already happened and prepare for what will

		int	res = 0;

		synchronized( rate_sem ){

			if ( rate_bytes_read > 0 ){

				res = rate_bytes_read;

				if ( res > max ){

					res = max;
				}

				rate_bytes_read -= res;
			}

			int	rem = max - res;

			if ( rem > rate_bytes_permitted ){

				if ( rate_bytes_permitted == 0 ){

					rate_sem.release();
				}

				rate_bytes_permitted = rem;
			}
		}

		return( res );
	}
}

public class SIZE {
/**
	 * @note bIncludeQueue can return an invalid number, such as a negative :(
	 */
	public int size(boolean bIncludeQueue) {
		int size = sortedRows.size();

		if (bIncludeQueue) {
			if (dataSourcesToAdd != null) {
				size += dataSourcesToAdd.size();
			}
			if (dataSourcesToRemove != null) {
				size -= dataSourcesToRemove.size();
			}
		}
		return size;
	}
}

public class SETISVISIBLE {
/**
	 * @param visible
	 *
	 * @since 3.0.4.3
	 */
	protected boolean setIsVisible(boolean visible, boolean walkup) {
		if ((visible ? 1 : 0) == isVisible) {
			return false;
		}
		if (SWTSkin.DEBUG_VISIBILITIES) {
			System.out.println(this + " SET IS VISIBLE " + visible + " via " + Debug.getCompressedStackTrace(9));
		}
		isVisible = visible ? 1 : 0;
		switchSuffix(null, 0, false);
		triggerListeners(visible ? SWTSkinObjectListener.EVENT_SHOW
				: SWTSkinObjectListener.EVENT_HIDE);

		// only walkup when visible.. yes?
		if (walkup && visible) {
			SWTSkinObject p = parent;

  		while (p instanceof SWTSkinObjectBasic) {
  			((SWTSkinObjectBasic) p).setIsVisible(visible, false);
  			p = ((SWTSkinObjectBasic) p).getParent();
  		}
		}
		return true;
	}
}

public class VALIDATEPERCENT {
/**
	 * @return
	 *
	 * @since 3.0.2.3
	 */
	private double validatePercent(double percent, boolean triggerListeners) {
		if (triggerListeners) {
			Object[] listenersArray = listeners.toArray();
			for (int i = 0; i < listenersArray.length; i++) {
				SWTSkinListenerSliderSelection l = (SWTSkinListenerSliderSelection) listenersArray[i];
				Double changedPercent = l.selectionChanging(this.percent, percent);
				if (changedPercent != null) {
					return changedPercent.floatValue();
				}
			}
		}

		if (percent < 0) {
			return 0;
		} else if (percent > 1) {
			return 1;
		}
		return percent;
	}
}

public class CONTAINSKEY {
/**
     * <p>Tests if the specified object is a key in this hashtable.</p>
     *
     * @param  key  possible key.
     * @return <code>true</code> if and only if the specified object is a
     *    key in this hashtable, as determined by the <tt>equals</tt>
     *    method; <code>false</code> otherwise.
     * @see #contains(Object)
     */
    public boolean containsKey(int key) {
        Entry tab[] = table;
        int hash = key;
        int index = (hash & 0x7FFFFFFF) % tab.length;
        for (Entry e = tab[index]; e != null; e = e.next) {
            if (e.hash == hash) {
                return true;
            }
        }
        return false;
    }
}

public class GETUPDATEOUTPUTSIZE {
/**
     * return the size of the output buffer required for an update 
     * an input of len bytes.
     *
     * @param len the length of the input.
     * @return the space required to accommodate a call to update
     * with len bytes of input.
     */
    public int getUpdateOutputSize(
        int len)
    {
        int total       = len + bufOff;
        int leftOver;

        if (pgpCFB)
        {
            leftOver    = total % buf.length - (cipher.getBlockSize() + 2);
        }
        else
        {
            leftOver    = total % buf.length;
        }

        return total - leftOver;
    }
}

public class GETOUTPUTSIZE {
/**
     * return the size of the output buffer required for an update plus a
     * doFinal with an input of len bytes.
     *
     * @param len the length of the input.
     * @return the space required to accommodate a call to update and doFinal
     * with len bytes of input.
     */
    public int getOutputSize(
        int len)
    {
        int total       = len + bufOff;
        int leftOver;

        if (pgpCFB)
        {
            leftOver    = total % buf.length - (cipher.getBlockSize() + 2);
        }
        else
        {
            leftOver    = total % buf.length;
            if (leftOver == 0)
            {
                return total;
            }
        }

        return total - leftOver + buf.length;
    }
}

