public class CUBICLOOP {
/**
 * 
 */
protected static double cubicLoop(int runs, int size) {
	double a = 1.123;
	double b = 1.000000000012345;
	for (int r=0; r<runs; r++) {
		for (int i=size; --i >= 0; ) {
			for (int j=size; --j >= 0; ) {
				for (int k=size; --k >= 0; ) {
					a *= b;
				}
			}
		}
	}
	return a;
}
}

