public class RELERROR {
/**
 * Computes the relative error (in percent) from one measure to another.
 */
protected double relError(double measure1, double measure2) {
	return 100 * (1 - measure1 / measure2);
}
}

public class HASSUMOFPOWERS {
/**
 * Tells whether <tt>sumOfPowers(k)</tt> can return meaningful results.
 * Defined as <tt>hasSumOfPowers(k) <==> getMinOrderForSumOfPowers() <= k && k <= getMaxOrderForSumOfPowers()</tt>.
 * A return value of <tt>true</tt> implies that <tt>hasSumOfPowers(k-1) .. hasSumOfPowers(0)</tt> will also return <tt>true</tt>.
 * See the constructors for proper parametrization.
 * <p>
 * <b>Details</b>: 
 * <tt>hasSumOfPowers(0..2)</tt> will always yield <tt>true</tt>.
 * <tt>hasSumOfPowers(-1) <==> hasSumOfInversions()</tt>.
 *
 * @return <tt>false</tt> if the bin was constructed with insufficient parametrization, <tt>true</tt> otherwise.
 * @see #getMinOrderForSumOfPowers()
 * @see #getMaxOrderForSumOfPowers()
 */
public boolean hasSumOfPowers(int k) {
	return getMinOrderForSumOfPowers() <= k && k <= getMaxOrderForSumOfPowers();
}
}

public class XHASSUMOFPOWERS {
/**
 * Tells whether <tt>sumOfPowers(fromK) .. sumOfPowers(toK)</tt> can return meaningful results.
 * @return <tt>false</tt> if the bin was constructed with insufficient parametrization, <tt>true</tt> otherwise.
 * See the constructors for proper parametrization.
 * @throws IllegalArgumentException if <tt>fromK > toK</tt>.
 */
protected boolean xhasSumOfPowers(int fromK, int toK) {
	if (fromK > toK) throw new IllegalArgumentException("fromK must be less or equal to toK");
	return getMinOrderForSumOfPowers() <= fromK && toK <= getMaxOrderForSumOfPowers();
}
}

public class SIZEOFRANGE {
/**
 * Returns how many elements are contained in the range <tt>[minElement,maxElement]</tt>.
 * Does linear interpolation if one or both of the parameter elements are not contained.
 * Returns exact or approximate results, depending on the parametrization of this class or subclasses.
 *
 * @param minElement the minimum element to search for.
 * @param maxElement the maximum element to search for.
 * @return the number of elements in the range.
 */
public int sizeOfRange(double minElement, double maxElement) {
	return (int) Math.round(size() * (quantileInverse(maxElement) - quantileInverse(minElement)));
}
}

public class MAP {
/**
	 * Package private method to map from the external representation of bin
	 * number to our internal representation of bin number
	 */
	int map(int index)
	{
		int bins = xAxis.bins()+2;
		if (index >= bins) throw new IllegalArgumentException("bin="+index);
		if (index >= 0) return index+1;
		if (index == IHistogram.UNDERFLOW) return 0;
		if (index == IHistogram.OVERFLOW) return bins-1;
		throw new IllegalArgumentException("bin="+index);
	}
}

