public class GETFIELDINDEX {
/**
	 * Get Field Index
	 * 
	 * @return Field with name or null
	 */
	public int getFieldIndex(int AD_Field_ID) {
		if (p_vos == null)
			return -1;
		for (int i = 0; i < p_vos.size(); i++) {
			UIField field = (UIField) p_vos.get(i);
			if (field.getAD_Field_ID() == AD_Field_ID)
				return i;
		}
		return -1;
	}
}

public class ISAPPSSERVEROK {
/**
	 *  Is Application Server OK
	 *  @param tryContactAgain try to contact again
	 *  @return true if Apps Server exists
	 */
	public boolean isAppsServerOK (boolean tryContactAgain)
	{
		if (!tryContactAgain)
			return m_okApps;

		if (m_iContext == null)
		{
			getInitialContext (false);
			if (!m_okApps)
				return false;
		}

		//	Contact it
		try
		{
			Status status = getStatusEjbStub();
			m_version = status.getDateVersion ();
			status.remove ();
			m_okApps = true;
		}
		catch (Exception ce)
		{
			log.severe(ce.getMessage());
			m_okApps = false;
		}
		catch (Throwable t)
		{
			log.severe(t.getMessage());
			m_okApps = false;
		}
		return m_okApps;
	}
}

public class GET_VALUEASINT {
/**
	 *  Get Value as int
	 *  @param index index
	 *  @return int value or 0
	 */
	protected int get_ValueAsInt (int index)
	{
		Object value = get_Value(index);
		if (value == null)
			return 0;
		if (value instanceof Integer)
			return ((Integer)value).intValue();
		try
		{
			return Integer.parseInt(value.toString());
		}
		catch (NumberFormatException ex)
		{
			log.warning(p_info.getColumnName(index) + " - " + ex.getMessage());
			return 0;
		}
	}
}

