public class SAVEFINISH {
/**
	 * 	Finish Save Process
	 *	@param newRecord new
	 *	@param success success
	 *	@return true if saved
	 */
	private boolean saveFinish (boolean newRecord, boolean success)
	{
		//	Translations
		if (success)
		{
			if (newRecord)
			{
				insertTranslations();
				insertSubTable();
				MRecentItem.add(this, "I");
			}
			else
			{
				updateTranslations();
				updateSubTable();
				MRecentItem.add(this, "U");
			}
			updatePreferences();
		}
		//
		try
		{
			success = afterSave (newRecord, success);
			if (success && newRecord)
				insertTreeNode();
		}
		catch (Exception e)
		{
			log.log(Level.WARNING, "afterSave", e);
			log.saveError("Error", e.toString(), false);
			success = false;
			//	throw new DBException(e);
		}
		//	OK
		if (success)
		{
			if (s_docWFMgr == null)
			{
				try
				{
					Class.forName("org.compiere.wf.DocWorkflowManager");
				}
				catch (Exception e)
				{
				}
			}
			if (s_docWFMgr != null)
				s_docWFMgr.process (this, p_info.getAD_Table_ID());

			//	Copy to Old values
			int size = p_info.getColumnCount();
			for (int i = 0; i < size; i++)
			{
				if (m_newValues[i] != null)
				{
					if (m_newValues[i] == Null.NULL)
						m_oldValues[i] = null;
					else
						m_oldValues[i] = m_newValues[i];
				}
			}
			m_newValues = new Object[size];
		}
		m_createNew = false;
		if (!newRecord) {
			CacheMgt.get().reset(p_info.getTableName());
		}
		return success;
	}
}

