	 *	@param includeSub
	 *	@return m_isUseAd
	 */
	public boolean isUseAd(boolean includeSub) 
	{
		if (!includeSub)
		{
			return isUseAd();
		} else {
			if (m_preBuildTemplate==null) 
				rebuildTemplate();
			if (!m_isUseAd && isUseAd()) 
				m_isUseAd = isUseAd();
			if (isUseAd())
				m_adTemplates.append (get_ID() + ",");
			return m_isUseAd;
		}
	}
}

