public class TEST {
/**************************************************************************
	 * 	Test
	 * 	@param finalIteration final test
	 *	@return true if test ok
	 */
	public boolean test(boolean finalIteration)
	{
		String error = testJava();
		if (error != null)
		{
			log.severe(error);
			return false;
		}

		error = testCompiere();
		if (error != null)
		{
			log.warning(error);
			return false;
		}
		if(p_panel != null)
			p_panel.setStatusBar(p_panel.lAppsServer.getText());

		error = testAppsServer();
		if (error != null)
		{
			log.warning(error);
			return false;
		}

		if(p_panel != null)
			p_panel.setStatusBar(p_panel.lDatabaseServer.getText());
		error = testDatabase();
		if (error != null)
		{
			log.warning(error);
			return false;
		}

		if(p_panel != null)
			p_panel.setStatusBar(p_panel.lMailServer.getText());

		error = testMail();
		if (error != null)
		{
			log.warning(error);
			return false;
		}

		return true;
	}
}

public class TESTSERVERPORT {
/**
	 * 	Test Server Port
	 *  @param port port
	 *  @return true if able to create
	 */
	protected boolean testServerPort (int port)
	{
		try
		{
			ServerSocket ss = new ServerSocket (port);
			log.fine(ss.getInetAddress() + ":" + ss.getLocalPort() + " - created");
			ss.close();
		}
		catch (Exception ex)
		{
			log.warning("Port " + port + ": " + ex.getMessage());
			return false;
		}
		return true;
	}
}

public class DOSELECTOPERATION {
/**
	  * executing a select and retrieving the results
	  * select the row with t_key value as 'selectWhat'
	  */
	 public int doSelectOperation(long selectWhat) {
		 int numRowsSelected = 0;
		 ResultSet rs = null;

		 try {
			 select.setLong(1,selectWhat);
			 rs = select.executeQuery();

			 while (rs.next()) {
				 numRowsSelected++;

				 int intVal = rs.getInt(1);
				 String strVal = rs.getString(2);
				 float floatVal = rs.getFloat(3);
				 long longVal = rs.getLong(4); 	//t_key column

				 pw.println("[NsSampleWork] Thread id - "+ thread_id +" selected "+numRowsSelected +" row ["+ intVal + ","
				 			+ strVal +","+ floatVal +","+ longVal +"]");
			 }
		 } catch (Exception e) {
			e.printStackTrace();
		   } finally {
			   try {
			 	if(rs != null)
					rs.close();
			   } catch (Exception e) {
				   e.printStackTrace();
			     }
		     }
		 return numRowsSelected;
	 }
}

public class WEIGHQUESTION {
/**
     * <p>
     * Compute the relative weight of a Question given its difficulty.
     * </p>
     */
    public static double weighQuestion(int difficulty)
    {
        return (double) difficulty;
    }
}

public class SCOREANSWER {
/**
     * <p>
     * Compute the score for a question. A penalty is assessed
     * for guessing the wrong answer. If actualChoice is -1,
     * then the Student didn't guess and we don't assess a penalty.
     * </p>
     */
    public static double scoreAnswer
        (
         int difficulty,
         int numberOfChoices,
         int correctChoice,
         int actualChoice
         )
    {
        if( actualChoice < 0 ) { return 0.0; }

        double weight = weighQuestion(difficulty);

        if ( correctChoice == actualChoice ) { return weight; }
        else
        {
            double penaltyRatio = 1.0 / ((double) numberOfChoices);
            return -(weight * penaltyRatio);
        }
    }
}

public class FINISHSCORE {
/**
     * <p>
     * Calculate the final score as a percentage, given the highest possible
     * score and the actual score achieved.
     * </p>
     */
    public static double finishScore(double allCorrect, double actual)
    {
        if ( actual < 0.0D ) { return 0.0D; }
        else { return (100D * actual) / allCorrect; }
    }
}

