public class GETINPUTJDBCTYPE {
/**
     * Convert the input targetJdbcType to the correct JdbcType used by CrossConverters.
     */
    public static int getInputJdbcType(int jdbcType) {
        switch (jdbcType) {
        case java.sql.Types.BIT:
        case java.sql.Types.BOOLEAN:
        case java.sql.Types.TINYINT:
        case java.sql.Types.SMALLINT:
            return java.sql.Types.INTEGER;
        case java.sql.Types.NUMERIC:
            return java.sql.Types.DECIMAL;
        case java.sql.Types.FLOAT:
            return java.sql.Types.DOUBLE;
        default:
            return jdbcType;
        }

    }
}

public class GETTIMESTAMPLENGTH {
/**
     * Return the length of a timestamp depending on whether timestamps
     * should have full nanosecond precision or be truncated to just microseconds.
     * java.sql.Timestamp is converted to a character representation which is a DERBY string 
     * representation of a timestamp converted to bytes using UTF8 encoding.
     * For Derby 10.6 and above, this is <code>yyyy-mm-dd-hh.mm.ss.fffffffff</code>.
     * For Derby 10.5 and below, this is <code>yyyy-mm-dd-hh.mm.ss.ffffff</code>. See DERBY-2602.
     * and then converted to bytes using UTF8 encoding
     *
     * @param supportsTimestampNanoseconds true if the connection supports nanoseconds in timestamps
     */
    public static int getTimestampLength( boolean supportsTimestampNanoseconds )
    {
        return supportsTimestampNanoseconds ?
            DRDAConstants.JDBC_TIMESTAMP_LENGTH : DRDAConstants.DRDA_TIMESTAMP_LENGTH;
    }
}

public class CHECKTYPE {
/**
         * This method return true if the type is possible.
         */
        boolean checkType(int type){

            if(SanityManager.DEBUG){

                for(int i = 0;
                    i < possibleTypes.length - 1;
                    i ++){

                    SanityManager.ASSERT(possibleTypes[i] < possibleTypes[i + 1]);

                }
            }

            return Arrays.binarySearch( possibleTypes,
                                        type ) >= 0;

        }
}

public class LOCATOR {
/**
     * Get locator for LOB of the designated column
     * <p>
     * Note that this method cannot be invoked on a LOB column that is NULL.
     *
     * @param column column number, starts at 1
     * @return locator value, <code>Lob.INVALID_LOCATOR</code> if LOB
     *         value was sent instead of locator
     */
    protected int locator(int column)
    {
        int locator = get_INTEGER(column);
        // If Lob value was sent instead of locator, the value will be
        // 0x8000, 0x8002, 0x8004, 0x8006, 0x8008. This is not a locator 
        // but the blob has been sent by value.
        // Zero is not a valid locator, it indicates a zero length value
        if ((locator == 0x8000) || (locator == 0x8002) || (locator == 0x8004) || 
                (locator == 0x8006) || (locator == 0x8008) ||(locator == 0)) {
            return Lob.INVALID_LOCATOR;
        } else {
            return locator;
        }
    }
}

