public class GETENCRYPTEDDATALENGTH {
/**
	   returns the length that will make the data to be multiple of encryption
	   block size based on the given length. Block cipher algorithms like DES 
	   and Blowfish ..etc  require their input to be an exact multiple of the block size.
	*/
	public int getEncryptedDataLength(int length)
	{
		if ((length % getEncryptionBlockSize()) != 0)
		{
			return length + getEncryptionBlockSize() - (length % getEncryptionBlockSize());
		}

		return length;
	}
}

public class CHECKVERSION {
/**
	   Check to see if a database has been upgraded to the required
	   level in order to use a store feature.
	   @param requiredMajorVersion  required database Engine major version
	   @param requiredMinorVersion  required database Engine minor version
	   @return True if the database has been upgraded to the required level, false otherwise.
	**/
	boolean checkVersion(int requiredMajorVersion, int requiredMinorVersion) 
	{
		if(onDiskMajorVersion > requiredMajorVersion )
		{
			return true;
		}
		else
		{
			if(onDiskMajorVersion == requiredMajorVersion &&  
			   onDiskMinorVersion >= requiredMinorVersion)
				return true;
		}

		return false;
	}
}

public class HASPREPAREDXACT {
/**
     * Is there a prepared transaction in the transaction table.
     * 
     * <P>MT - unsafe, caller is recovery/at boot, which is single threaded.
     *
     * @param recovered  <code> true </code> to search  for transaction 
     *                  that are in prepared during recovery.  
     *                  recovered tranaction. 
     *                  <code> false > to search for just prepared 
     *                  transactons. 
     * @return         <code> true if there is a prepared transaction and
     *                  recovered when <code> recovered </code> argument is 
     *                  <code> true </code>
     */

    private boolean hasPreparedXact(boolean recovered)
    {
        for (Iterator it = trans.values().iterator(); it.hasNext(); )
        {
            TransactionTableEntry ent = (TransactionTableEntry) it.next();

            if (ent != null && 
                (ent.getTransactionStatus() & Xact.END_PREPARED) != 0)
            {
                if (recovered) {
                    if(ent.isRecovery())
                        return true;
                } else {
                    return true;
                }
            }
        }
        return false;
    }
}

public class ATLEAST {
/**
	 * <p>
	 * Return true if we are at least at the passed in version.
	 * </p>
	 */
	public	boolean	atLeast( int baseMajor, int baseMinor )
	{
		if ( major < baseMajor ) { return false; }
		if ( major > baseMajor ) { return true; }

		// same major number

		return ( minor >= baseMinor );
	}
}

public class GETFIRSTINDEXFORPAGE {
/**
     * Returns the index into the master list of the first object that should appear on the given page.
     * @param pageNumber page number
     * @return int index of the first object that should appear on the given page
     */
    protected int getFirstIndexForPage(int pageNumber)
    {
        int retval = (pageNumber - 1) * this.pageSize;
        return retval >= 0 ? retval : 0;
    }
}

public class GETLASTINDEXFORPAGE {
/**
     * Returns the index into the master list of the last object that should appear on the given page.
     * @param pageNumber page number
     * @return int index of the last object that should appear on the given page
     */
    protected int getLastIndexForPage(int pageNumber)
    {

        int firstIndex = getFirstIndexForPage(pageNumber);
        int pageIndex = this.pageSize - 1;
        int lastIndex = this.fullListSize - 1;

        return Math.min(firstIndex + pageIndex, lastIndex);
    }
}

public class GETKERNINGOFFSET {
/**
     * Get the kerning adjustment required between the two given codes
     */
    public double getKerningOffset( int code1, int code2 )
    {        
        if( kernLookup == null )
        {
            kernLookup = new HashMap();

            for( Iterator it = kerning.iterator(); it.hasNext(); )
            {
                KerningPair pair = (KerningPair)it.next();
                Integer i1 = new Integer( pair.code1 );
                Integer i2 = new Integer( pair.code2 );

                HashMap kerns = (HashMap)kernLookup.get( i1 );

                if( kerns == null )
                {
                    kerns = new HashMap();
                    kernLookup.put( i1, kerns );
                }

                kerns.put( i2, pair );
            }
        }

        Integer i1 = new Integer( code1 );
        Integer i2 = new Integer( code2 );

        HashMap kerns = (HashMap)kernLookup.get( i1 );
        if( kerns == null ) return 0.0;

        KerningPair pair = (KerningPair)kerns.get( i2 );
        if( pair == null ) return 0.0;

        return pair.adjustment;
    }
}

public class GETKERNINGOFFSET {
/**
     * Get the kerning adjustment required between the two given codes
     */
    public double getKerningOffset(int code1, int code2)
    {
        double ret;

        Integer i1 = new Integer(code1);
        Integer i2 = new Integer(code2);

        if (kernLookup == null)
        {
            kernLookup = new HashMap();

            if (kerning.size() != 0)
                throw new IllegalStateException("Internal Error in SystemFontDefinition: no kernLookup, but kerning contains entries!");
        }
        else
        {
            HashMap kerns = (HashMap) kernLookup.get(i1);
            if (kerns != null)
            {
                KerningPair pair = (KerningPair) kerns.get(i2);
                if (pair != null)
                {
                    return pair.getAdjustment();
                }
            }
        }

        ret = calculateKerningOffset(code1, code2);

        HashMap kerns = (HashMap) kernLookup.get(i1);
        if (kerns == null)
        {
            kerns = new HashMap();
            kernLookup.put(i1, kerns);
        }

        kerns.put(i2, new KerningPair(code1, code2, ret));

        return ret;
    }
}

public class CALCULATEKERNINGOFFSET {
/**
     * Calculate the Kerning Offset of the specified characters. This is a hack,
     * because the Java Font API doesn't expose Kerning information directly.
     * @return adjustment needed between this two codes.
     */
    private double calculateKerningOffset(int code1, int code2)
    {
        char[] chars =
        { (char) code1, (char) code2 };
        GlyphVector gv = font.createGlyphVector(frc, chars);

        //        double adj = (gv.getGlyphPosition(1).getX() - metrics.charWidth(chars[0])) * scale;
        double adj = (gv.getGlyphPosition(1).getX() - gv.getGlyphMetrics(0).getAdvanceX()) * scale;

        if (DEBUG_KERNING) System.out.println("Kerning for '" + (char) code1 + (char) code2 + "': " + adj);

        return adj;
    }
}

public class GETBIT {
/**
     * Get the given bit (where lowest bit is numbered 1)
     */
    public static boolean getBit( int bitNum, long value )
    {
        return (value & (1L << (bitNum - 1))) != 0;
    }
}

public class SETBIT {
/**
     * Set the given bit (where lowest bit is numbered 1)
     */    
    public static int setBit( int bitNum, int value )
    {
        return value | ( 1 << (bitNum-1) );
    }
}

public class DETERMINESIGNEDBITSIZE {
/**
     * Determine the minimum number of bits required to hold the given
     * signed value
     */
    public static int determineSignedBitSize( int value )
    {
        if( value >= 0 ) return determineUnsignedBitSize( value ) + 1;

        //--This is probably a really bad way of doing this...
        int  topBit = 31;
        long mask = 0x40000000L;

        while( topBit > 0 )
        {
            if( (value & mask) == 0 ) break;

            mask >>= 1;
            topBit--;
        }

        if( topBit == 0 ) return 2;  //must have been -1

        //HACK: Flash represents -16 as 110000 rather than 10000 etc..
        int val2 = value & (( 1 << topBit) - 1 );
        if( val2 == 0 )
        {
            topBit++;
        }

        return topBit + 1;
    }
}

public class DETERMINEUNSIGNEDBITSIZE {
/**
     * Determine the minimum number of bits required to hold the given
     * unsigned value (may be zero)
     */
    public static int determineUnsignedBitSize( long value )
    {
        //--This is probably a really bad way of doing this...
        int  topBit = 32;
        long mask = 0x80000000L;

        while( topBit > 0 )
        {
            if( (value & mask) != 0 ) return topBit;

            mask >>= 1;
            topBit--;
        }

        return 0;
    }
}

public class CONVERTENTIRECOLORLINEARRGBTOSRGB {
/** Yet another helper function.  This one extracts the color components
     * of an integer RGB triple, converts them from LinearRGB to SRGB, then
     * recompacts them into an int.
     */
    private int convertEntireColorLinearRGBtoSRGB(int rgb) {

        int a1, r1, g1, b1; //color components

        //extract red, green, blue components
        a1 = (rgb >> 24) & 0xff;
        r1 = (rgb >> 16) & 0xff;
        g1 = (rgb >> 8) & 0xff;
        b1 = rgb & 0xff;

        //use the lookup table
        r1 =  LinearRGBtoSRGB[r1];
        g1 =  LinearRGBtoSRGB[g1];
        b1 =  LinearRGBtoSRGB[b1];

        //re-compact the components
        return ((a1 << 24) |
                (r1 << 16) |
                (g1 << 8) |
                b1);
    }
}

public class CONVERTENTIRECOLORSRGBTOLINEARRGB {
/** Yet another helper function.  This one extracts the color components
     * of an integer RGB triple, converts them from LinearRGB to SRGB, then
     * recompacts them into an int.
     */
    private int convertEntireColorSRGBtoLinearRGB(int rgb) {

        int a1, r1, g1, b1; //color components

        //extract red, green, blue components
        a1 = (rgb >> 24) & 0xff;
        r1 = (rgb >> 16) & 0xff;
        g1 = (rgb >> 8) & 0xff;
        b1 = rgb & 0xff;

        //use the lookup table
        r1 =  SRGBtoLinearRGB[r1];
        g1 =  SRGBtoLinearRGB[g1];
        b1 =  SRGBtoLinearRGB[b1];

        //re-compact the components
        return ((a1 << 24) |
                (r1 << 16) |
                (g1 << 8) |
                b1);
    }
}

public class CONVERTSRGBTOLINEARRGB {
/** Helper function to convert a color component in sRGB space to linear
     * RGB space.  Used to build a static lookup table.
     */
    private static int convertSRGBtoLinearRGB(int color) {

        float input, output;

        input = ((float) color) / 255.0f;
        if (input <= 0.04045f) {
            output = input / 12.92f;
        }
        else {
            output = (float) Math.pow((input + 0.055) / 1.055, 2.4);
        }
        int o = Math.round(output * 255.0f);

        return o;
    }
}

public class CONVERTLINEARRGBTOSRGB {
/** Helper function to convert a color component in linear RGB space to
      *  SRGB space. Used to build a static lookup table.
      */
    private static int convertLinearRGBtoSRGB(int color) {

        float input, output;

        input = ((float) color) / 255.0f;

        if (input <= 0.0031308) {
            output = input * 12.92f;
        }
        else {
            output = (1.055f *
                ((float) Math.pow(input, (1.0 / 2.4)))) - 0.055f;
        }

        int o = Math.round(output * 255.0f);

        return o;
    }
}

public class CHECKHEAPSIZE {
/** @return true if a JVM can be created with the specified heap size (in MB) */
  public static boolean checkHeapSize(long heapSize) {
    int exitValue = 1;
    try {
      JVMBuilder jvmb = JVMBuilder.DEFAULT.jvmArguments("-Xmx"+heapSize+"M");
      Process p = jvmb.start(MemoryCheckDummy.class.getName());
      exitValue = p.waitFor();
    }
    catch(java.io.IOException e) { exitValue = 1; }
    catch(InterruptedException e) { exitValue = 1; }
    return (exitValue==0);
  }
}

public class ISSHADOWED {
