public class GETINTVALUE {
/** return an int on the stack, or 'defaultValue' if can't determine */
	private int getIntValue(int stackDepth, int defaultValue) {
		if (stack.getStackDepth() < stackDepth) return defaultValue;
		OpcodeStack.Item it = stack.getStackItem(stackDepth);
		Object value = it.getConstant();
		if (value == null || !(value instanceof Integer)) return defaultValue;
		return ((Number)value).intValue();
	}
}

public class STACKENTRYTHATMUSTBENONNEGATIVE {
/**
	 * Return index of stack entry that must be nonnegative.
	 *
	 * Return -1 if no stack entry is required to be nonnegative.
	 * @param seen
	 * @return
	 */
	private int stackEntryThatMustBeNonnegative(int seen) {
		switch(seen) {
		case INVOKEINTERFACE:
			if (getClassConstantOperand().equals("java/util/List")) {
				return getStackEntryOfListCallThatMustBeNonnegative();
			}
			break;
		case INVOKEVIRTUAL:
			if (getClassConstantOperand().equals("java/util/LinkedList") || getClassConstantOperand().equals("java/util/ArrayList")) {
				return getStackEntryOfListCallThatMustBeNonnegative();
			}
			break;

		case IALOAD:
		case AALOAD:
		case SALOAD:
		case CALOAD:
		case BALOAD:
		case LALOAD:
		case DALOAD:
		case FALOAD:
			return 0;
		case IASTORE:
		case AASTORE:
		case SASTORE:
		case CASTORE:
		case BASTORE:
		case LASTORE:
		case DASTORE:
		case FASTORE:
			return 1;
		}
		return -1;
	}
}

