public class MATCHES {
/**
     * Returns true if the given number matches this relation.
     *
     * @param number a <code>double</code> value
     * @return a <code>boolean</code> value
     */
    public boolean matches(double number) {
	double value = (mod == 1) ? number : number % mod;
	if (integer && value != (int) value) {
	    return false;
	}
	return (low <= value && value <= high) != negated;
    }
}

public class MATCHES {
/**
     * Returns true if this rule matches the given number.
     *
     * @param number a <code>double</code> value
     * @return a <code>boolean</code> value
     */
    public boolean matches(double number) {

	outer: for (List<Relation> andCondition : conditions) {
	    for (Relation relation : andCondition) {
		if (!relation.matches(number)) {
		    continue outer;
		}
	    }
	    return true;
	}
	return false;

    }
}

public class ISCELLEDITABLE {
/**
         * Returns 'true' if the specified cell is editable, 'false' otherwise.
         *
         * @param row The specified row.
         * @param column The specified column.
         * @return 'true' if the specified cell is editable, 'false' otherwise.
         */
        public boolean isCellEditable(int row, int column) {
            if ((row >= 0) && (row < nations.size())) {
                Nation nation = nations.get(row);
                boolean ownRow = (thisPlayer == players.get(nation) && !thisPlayer.isReady());
                switch(column) {
                case AVAILABILITY_COLUMN:
                    return (!ownRow && thisPlayer.isAdmin());
                case ADVANTAGE_COLUMN:
                case COLOR_COLUMN:
                    return (nation.getType() instanceof EuropeanNationType && ownRow);
                case PLAYER_COLUMN:
                    return (nation.getType() instanceof EuropeanNationType && players.get(nation) == null);
                }
            }
            return false;
        }
}

