public class ALMOSTEQUALS {
/**
   * The cycleDuration and cycleDelay are simulated by sleeping for those
   * numbers of milliseconds.  Since sleep() is inexact, we'll assume it may
   * vary by +/- 1 msec per call.  Since there are two calls per
   * virtual cycle, the potential error is twice that.  And we add 1 to
   * account for sheer paranoia and the possibility of two consecutive 
   * calls to "now()" occurring across a tick boundary.
   * We'll use values > 10 for cycleDuration and cycleDelay,
   * so the error isn't huge, percentage-wise.
   * 
   * @return - whether the difference between inputs a and b is within
   * that expected error
   */
  private boolean almostEquals(long a, long b) {
    long diff = a - b;
    if (diff < 0) diff = -diff;
    return diff < 2 * (qStats.cycleCount + 1);
  }
}

public class GETRANDOM {
/**
     * Return a random number between 0 and N inclusive.
     *
     * @param int n
     * @param n  max number to return
     * @return random integer between 0 and N
     */
    private int getRandom(int n) {
        return (int) (n * Math.random());
    }
}

public class WITHINTOLERANCE {
/**
     * Calculate if the error in expected and observed values is within tolerance
     *
     * @param expectedValue  expected value of experiment
     * @param observedValue  observed value of experiment
     * @param tolerance      per cent tolerance for error, represented as a int
     */
    private boolean withinTolerance(long expectedValue,
                                    long observedValue,
                                    int tolerance) {
        double diff = 1.0 * Math.abs(observedValue - expectedValue);
        double thrs = expectedValue * (tolerance/100);
        return diff > thrs;
    }
}

public class CANRESPONSEHAVEBODY {
/**
     * Per RFC 2616 section 4.3, some response can never contain a message
     * body.
     *
     * @param status - the HTTP status code
     *
     * @return <tt>true</tt> if the message may contain a body, <tt>false</tt> if it can not
     *         contain a message body
     */
    private static boolean canResponseHaveBody(int status) {
        LOG.trace("enter HttpMethodBase.canResponseHaveBody(int)");

        boolean result = true;

        if ((status >= 100 && status <= 199) || (status == 204)
            || (status == 304)) { // NOT MODIFIED
            result = false;
        }

        return result;
    }
}

public class HAVESEEN {
/**
     * Indicates, based on a PDFObject's generation/id pair whether
     * the parser has already encountered this object (or a reference to it)
     * so we don't infinitely loop on circuits within the PDF.
     * @param generation
     * @param id
     * @return True if already seen.
     */
    protected boolean haveSeen(int generation, int id){

        // if we can't store this generation grow our list until we can
        if(generation >= encounteredReferences.size()){
            for(int i=encounteredReferences.size(); i <= generation; i++){
                encounteredReferences.add(new ArrayList<Integer>());
            }

            // clearly we haven't seen it
            return false;
        }

        ArrayList<Integer> generationList
         = encounteredReferences.get(generation);

        for (int i: generationList) {
            if(i == id){
                return true;
            }
        }
        return false;
    }
}

public class INCREMENTSESSIONBALANCE {
/**
     * Increase the internal running budget to be used before 
     * deactivating the queue
     * 
     * @param amount amount to increment
     * @return updated budget value
     */
    public int incrementSessionBalance(int amount) {
        this.sessionBalance = this.sessionBalance + amount;
        return this.sessionBalance;
    }
}

public class EXPEND {
/**
     * Decrease the internal running budget by the given amount. 
     * @param amount tp decrement
     * @return updated budget value
     */
    public int expend(int amount) {
        this.sessionBalance = this.sessionBalance - amount;
        this.totalExpenditure = this.totalExpenditure + amount;
        this.lastCost = amount;
        this.costCount++;
        return this.sessionBalance;
    }
}

public class REFUND {
/**
     * A URI should not have been charged against queue (eg
     * it was disregarded); return the amount expended 
     * @param amount to return
     * @return updated budget value
     */
    public int refund(int amount) {
        this.sessionBalance = this.sessionBalance + amount;
        this.totalExpenditure = this.totalExpenditure - amount;
        this.costCount--;
        return this.sessionBalance;
    }
}

public class INDEXFOR {
/**
     * Return index for hash code h.
     */
    static int indexFor(int h, int length) {
        return h & (length-1);
    }
}

public class QUICKCHECK {
/**
     * Evaluate if quick-check cache considers fingerprint novel enough
     * for further consideration. 
     * 
     * @param fp long fingerprint to check
     * @return true if fp deserves consideration; false if it appears in cache
     */
    private boolean quickCheck(long fp) {
        return quickCache.add(fp);
    }
}

public class ENDSWITH {
/**
           Tests if this string ends with a character.
           @param ch the character to test for
           @return true if and only if this string ends with ch
        */
        boolean endsWith(char ch) {
            assert checkInvariants();
            int len = string.length();
            return (0 != len) && (string.charAt(len - 1) == ch);
        }
}

