/**
           Tests if this path is longer than a given value.
           @param maxLen the value to test
           @return true if and only if this path is longer than maxLen
        */
        boolean longerThan(int maxLen) {
            return filePath.getPath().length() > maxLen;
        }
}

public class CHARAT {
/**
     * Get character at passed absolute position.
     *
     * Called by {@link #charAt(int)} which has a relative index into the
     * content, one that doesn't account for HTTP header if present.
     *
     * @param index Index into content adjusted to accomodate initial offset
     * to get us past the HTTP header if present (i.e.
     * {@link #contentOffset}).
     *
     * @return Characater at offset <code>index</code>.
     */
    public char charAt(int index) {
        int c = -1;
        // Add to index start-of-content offset to get us over HTTP header
        // if present.
        index += this.contentOffset;
        if (index < this.prefixBuffer.length) {
            // If index is into our prefix buffer.
            c = this.prefixBuffer[index];
        } else if (index >= this.wrapOrigin &&
            (index - this.wrapOrigin) < this.wraparoundBuffer.length) {
            // If index is into our buffer window on underlying backing file.
            c = this.wraparoundBuffer[
                    ((index - this.wrapOrigin) + this.wrapOffset) %
                        this.wraparoundBuffer.length];
        } else {
            // Index is outside of both prefix buffer and our buffer window
            // onto the underlying backing file.  Fix the buffer window
            // location.
            c = faultCharAt(index);
        }
        // Stream is treated as single byte.  Make sure characters returned
        // are not negative.
        return (char)(c & 0xff);
    }
}

public class FAULTCHARAT {
/**
     * Get a character that's outside the current buffers.
     *
     * will cause the wraparoundBuffer to be changed to
     * cover a region including the index
     *
     * if index is higher than the highest index in the
     * wraparound buffer, buffer is moved forward such
     * that requested char is last item in buffer
     *
     * if index is lower than lowest index in the
     * wraparound buffer, buffet is reset centered around
     * index
     *
     * @param index Index of character to fetch.
     * @return A character that's outside the current buffers
     */
    private int faultCharAt(int index) {
        if(Thread.interrupted()) {
            throw new RuntimeException("thread interrupted");
        }
        if(index >= this.wrapOrigin + this.wraparoundBuffer.length) {
            // Moving forward
            while (index >= this.wrapOrigin + this.wraparoundBuffer.length)
            {
                // TODO optimize this
                advanceBuffer();
            }
            return charAt(index - this.contentOffset);
        }
        // Moving backward
        recenterBuffer(index);
        return charAt(index - this.contentOffset);
    }
}

public class CONTAINS {
/**
     * Does this set contain the given value?
     *
     * @see org.archive.util.fingerprint.LongFPSet#contains(long)
     */
    public boolean contains(long val) {
        long i = indexFor(val);
        if (slotHasData(i)) {
            noteAccess(i);
            return true;
        }
        return false;
    }
}

public class ADD {
/**
     * Add the given value to this set
     *
     * @see org.archive.util.fingerprint.LongFPSet#add(long)
     */
    public boolean add(long val) {
        logger.finest("Adding " + val);
        long i = indexFor(val);
        if (slotHasData(i)) {
            // positive index indicates already in set
            return false;
        }
        // we have a possible slot now, which is encoded as a negative number

        // check for space, and grow if needed
        if ((count + 1) > (loadFactor * (1 << capacityPowerOfTwo))) {
            makeSpace();
            // find new i
            i = indexFor(val);
            assert i < 0 : "slot should be empty";
        }

        i = asDataSlot(i); // convert to positive index
        setAt(i, val);
        count++;
        noteAccess(i);
        return true;
    }
}

public class INDEXFOR {
/** 
     * Given a value, check the store for its existence. If it exists, it
     * will return the index where the value resides.  Otherwise it return
     * an encoded index, which is a possible storage location for the value.
     *
     * <p>Note, if we have a loading factor less than 1.0, there should always
     * be an empty location where we can store the value
     *
     * @param val the fingerprint value to check for
     * @return The (positive) index where the value already resides,
     * or an empty index where it could be inserted (encoded as a
     * negative number).
     */
    private long indexFor(long val) {
        long candidateIndex = startIndexFor(val);
        while (true) {
            if (getSlotState(candidateIndex) < 0) {
                // slot empty; return negative number encoding index
                return asEmptySlot(candidateIndex);
            }
            if (getAt(candidateIndex) == val) {
                // already present; return positive index
                return candidateIndex;
            }
            candidateIndex++;
            if (candidateIndex == 1 << capacityPowerOfTwo) {
                candidateIndex = 0; // wraparound
            }
        }
    }
}

public class STARTINDEXFOR {
/**
     * Return the recommended storage index for the given value.
     * Assumes values are already well-distributed; merely uses
     * high-order bits.
     *
     * @param val
     * @return The recommended storage index for the given value.
     */
    private long startIndexFor(long val) {
        return (val >>> (64 - capacityPowerOfTwo));
    }
}

public class QUICKCONTAINS {
/**
     * Low-cost, non-definitive (except when true) contains
     * test. Default answer of false is acceptable.
     *
     * @see org.archive.util.fingerprint.LongFPSet#quickContains(long)
     */
    public boolean quickContains(long fp) {
        return false;
    }
}

public class ASDATASLOT {
/**
     * given a slot index, which could or could not be empty, return it as
     * a slot index indicating an non-empty slot
     *
     * @param index the slot index to convert
     * @return the index, converted to represent an slot with data
     */
    private long asDataSlot(final long index) {
        if (slotHasData(index)) { // slot already has data
            return index;
        }
        return - (index + 1);
    }
}

public class ASEMPTYSLOT {
/** 
     * Given a slot index, which could or could not be empty, return it as
     * a slot index indicating an empty slot
     * @param index the slot index to convert
     * @return the index, converted to represent an empty slot
     */
    private long asEmptySlot(final long index) {
        if (!slotHasData(index)) { // already empty slot
            return index;
        }
        return -index - 1;
    }
}

public class SLOTHASDATA {
/** 
     * Does this index represent a slot with data?
     *
     * @param index the index to check
     * @return <code>true</code> if the slot has data
     */
    private boolean slotHasData(final long index) {
        return index >= 0;
    }
}

public class GETBIT {
/**
     * Returns from the local bitvector the value of the bit with 
     * the specified index. The value is <tt>true</tt> if the bit 
     * with the index <tt>bitIndex</tt> is currently set; otherwise, 
     * returns <tt>false</tt>.
     *
     * (adapted from cern.colt.bitvector.QuickBitVector)
     * 
     * @param     bitIndex   the bit index.
     * @return    the value of the bit with the specified index.
     */
    protected boolean getBit(long bitIndex) {
        return ((bits[(int)(bitIndex >> ADDRESS_BITS_PER_UNIT)] & (1 << (bitIndex & BIT_INDEX_MASK))) != 0);
    }
}

public class GETBIT {
/**
     * Returns from the local bitvector the value of the bit with 
     * the specified index. The value is <tt>true</tt> if the bit 
     * with the index <tt>bitIndex</tt> is currently set; otherwise, 
     * returns <tt>false</tt>.
     *
     * (adapted from cern.colt.bitvector.QuickBitVector)
     * 
     * @param     bitIndex   the bit index.
     * @return    the value of the bit with the specified index.
     */
    protected boolean getBit(long bitIndex) {
        long intIndex = (bitIndex >>> ADDRESS_BITS_PER_UNIT);
        return ((bits[(int)(intIndex / ONE_MB_INTS)][(int)(intIndex % ONE_MB_INTS)] 
            & (1 << (bitIndex & BIT_INDEX_MASK))) != 0);
    }
}

public class SETGETBIT {
/**
     * Sets the bit with index <tt>bitIndex</tt> in local bitvector -- 
     * returning the old value. 
     *
     * (adapted from cern.colt.bitvector.QuickBitVector)
     * 
     * @param     bitIndex   the index of the bit to be set.
     */
    protected boolean setGetBit(long bitIndex) {
        long intIndex = (int) (bitIndex >>> ADDRESS_BITS_PER_UNIT);
        int a = (int)(intIndex / ONE_MB_INTS);
        int b = (int)(intIndex % ONE_MB_INTS);
        int mask = 1 << (bitIndex & BIT_INDEX_MASK);
        boolean ret = ((bits[a][b] & (mask)) != 0);
        bits[a][b] |= mask;
        return ret;
    }
}

