public class DECODE {
/**
     * Returns the Unicode character for the given Cp1252 byte.
     * 
     * @param b   an unsigned byte from 0 to 255
     * @return  the Unicode character corresponding to that byte
     */
    public static char decode(int b) {
        return XLAT[b];
    }
}

public class CORRECTPOI {
/**
     * Corrects POI's Cp1252 output.  There's a bug somewhere in POI that
     * makes it produce incorrect characters.  Not sure where and don't have
     * time to track it down.  But I have visually checked the input 
     * documents to verify that Doc is producing the right character, and
     * that POI is not.
     * 
     * @param ch  the POI-produced character to check
     * @return    the corrected character
     */
    private static int correctPOI(int ch) {
        switch (ch) {
            case 8734:
                // POI produced the infinity sign when it should have 
                // produced the degrees sign.
                return 176;
            case 214:
                // POI produced an umat O instead of an ellipses mark.
                return 8230;
            case 237:
                // POI produced an acute i instead of a fancy single quote
                return 8217;
            case 236:
                // POI produced a reverse acute i instead of fancy double quote
                return 8220;
            case 238:
                // POI produced a caret i instead of fancy double quote
                return 8221;
            default:
                return ch;
        }
    }
}

public class REDUCE {
/** Return a value equal (mod <code>polynomial</code>) to
        <code>fp</code> and of degree less than <code>degree</code>. */
    public long reduce(long fp) {
        int N = (8 - degree/8);
        long local = (N == 8 ? 0 : fp & (-1L << 8*N));
        long temp = zero;
        for (int i = 0; i < N; i++) {
            temp ^= ByteModTable[8+i][((int)fp) & 0xff];
            fp >>>= 8;
        };
        return local ^ temp;
    }
}

public class EXTEND_BYTE {
/** Extends <code>f</code> with lower eight bits of <code>v</code>
        with<em>out</em> full reduction.  In other words, returns a
        polynomial that is equal (mod <code>polynomial</code>) to the
        desired fingerprint but may be of higher degree than the
        desired fingerprint. */
    public long extend_byte(long f, int v) {
        f ^= (0xff & v);
        int i = (int)f;
        long result = (f>>>8);
        result ^= ByteModTable[7][i & 0xff];
        return result;
    }
}

public class EXTEND_CHAR {
/** Extends <code>f</code> with lower sixteen bits of <code>v</code>.
        Does not reduce. */
    public long extend_char(long f, int v) {
        f ^= (0xffff & v);
        int i = (int)f;
        long result = (f>>>16);
        result ^= ByteModTable[6][i & 0xff]; i >>>= 8;
        result ^= ByteModTable[7][i & 0xff];
        return result;
    }
}

public class EXTEND_INT {
/** Extends <code>f</code> with (all bits of) <code>v</code>.
        Does not reduce. */
    public long extend_int(long f, int v) {
        f ^= (0xffffffffL & v);
        int i = (int)f;
        long result = (f>>>32);
        result ^= ByteModTable[4][i & 0xff]; i >>>= 8;
        result ^= ByteModTable[5][i & 0xff]; i >>>= 8;
        result ^= ByteModTable[6][i & 0xff]; i >>>= 8;
        result ^= ByteModTable[7][i & 0xff];
        return result;
    }
}

public class EXTEND_LONG {
/** Extends <code>f</code> with <code>v</code>.
        Does not reduce. */
    public long extend_long(long f, long v) {
        f ^= v;
        long result = ByteModTable[0][(int)(f & 0xff)]; f >>>= 8;
        result ^= ByteModTable[1][(int)(f & 0xff)]; f >>>= 8;
        result ^= ByteModTable[2][(int)(f & 0xff)]; f >>>= 8;
        result ^= ByteModTable[3][(int)(f & 0xff)]; f >>>= 8;
        result ^= ByteModTable[4][(int)(f & 0xff)]; f >>>= 8;
        result ^= ByteModTable[5][(int)(f & 0xff)]; f >>>= 8;
        result ^= ByteModTable[6][(int)(f & 0xff)]; f >>>= 8;
        result ^= ByteModTable[7][(int)(f & 0xff)];
        return result;
    }
}

public class EXTEND {
/** Extends fingerprint <code>f</code> by adding (all bits of)
        "v". */
    public long extend(long f, char v) {
        return reduce(extend_char(f, v));
    }
}

public class EXTEND {
/** Extends fingerprint <code>f</code> by adding (all bits of)
        "v". */
    public long extend(long f, int v) {
        return reduce(extend_int(f, v));
    }
}

public class EXTEND {
/** Extends fingerprint <code>f</code> by adding (all bits of)
        "v". */
    public long extend(long f, long v) {
        return reduce(extend_long(f, v));
    }
}

public class GETDATETIMEPART {
/**
     * Returns the indicated part of the given <code>java.util.Date</code> object.
     * @param m the millisecond time value from which to extract the indicated part
     * @param part an integer code corresponding to the desired date part
     * @return the indicated part of the given <code>java.util.Date</code> object
     */
    public static int getDateTimePart(long m, int part) {

        synchronized (tempCalGMT) {
            tempCalGMT.setTimeInMillis(m);

            return tempCalGMT.get(part);
        }
    }
}

public class ISZEROBIT {
/**
         * Checks whether the specified bit is not set.
         *
         * @param bit
         */
        private boolean isZeroBit(int bit) {
            return (state & (1L << bit)) == 0;
        }
}

public class GETHEXVALUE {
/**
     * returns hex value of a hex character, or 16 if not a hex character
     */
    static int getHexValue(int c) {

        if (c >= '0' && c <= '9') {
            c -= '0';
        } else if (c > 'z') {
            c = 16;
        } else if (c >= 'a') {
            c -= ('a' - 10);
        } else if (c > 'Z') {
            c = 16;
        } else if (c >= 'A') {
            c -= ('A' - 10);
        } else {
            c = -1;
        }

        return c;
    }
}

public class GETNEXTCONSTRAINTINDEX {
/**
     *  Returns the next constraint of a given type
     *
     * @param  from
     * @param  type
     */
    int getNextConstraintIndex(int from, int type) {

        for (int i = from, size = constraintList.length; i < size; i++) {
            Constraint c = constraintList[i];

            if (c.getConstraintType() == type) {
                return i;
            }
        }

        return -1;
    }
}

public class GETOPERATIONTYPE {
