public class GETMAXLINEWIDTH {
/**
   * Returns the maximum line width in the specified line range.
   * @param start The first line
   * @param len The number of lines
   */
  public int getMaxLineWidth(int start, int len)
  {
    int retVal = 0;
    for(int i = start; i <= start + len; i++)
    {
      if(i >= length)
        break;
      retVal = Math.max(lineInfo[i].width,retVal);
    }
    return retVal;
  }
}

public class SETLINEWIDTH {
/**
   * Store the width of a line, in pixels.
   * @param lineIndex The line number
   * @param width The width
   */
  public boolean setLineWidth(int lineIndex, int width)
  {
    LineInfo info = lineInfo[lineIndex];
    int oldWidth = info.width;
    info.width = width;
    return width != oldWidth;
  }
}

public class SETORIGIN {
/**
    * A fast way of changing both the first line and horizontal
    * offset.
    * @param firstLine The new first line
    * @param horizontalOffset The new horizontal offset
    * @return True if any of the values were changed, false otherwise
    */
  public boolean setOrigin(int firstLine, int horizontalOffset)
  {
    boolean changed = false;
    int oldFirstLine = this.firstLine;

    if (horizontalOffset != this.horizontalOffset)
    {
      this.horizontalOffset = horizontalOffset;
      changed = true;
    }

    if (firstLine != this.firstLine)
    {
      this.firstLine = firstLine;
      changed = true;
    }

    if (changed)
    {
      updateScrollBars();
      painter.repaint();
      gutter.repaint();
    }

    return changed;
  }
}

public class SCROLLTO {
/**
    * Ensures that the specified line and offset is visible by scrolling
    * the text area if necessary.
    * @param line The line to scroll to
    * @param offset The offset in the line to scroll to
    * @return True if scrolling was actually performed, false if the
    * line and offset was already visible
    */
  public boolean scrollTo(int line, int offset)
  {
    // visibleLines == 0 before the component is realized
    // we can't do any proper scrolling then, so we have
    // this hack...
    if (visibleLines == 0)
    {
      setFirstLine(Math.max(0, line - electricScroll));
      return true;
    }

    int newFirstLine = firstLine;
    int newHorizontalOffset = horizontalOffset;

    if (line < firstLine + electricScroll)
    {
      newFirstLine = Math.max(0, line - electricScroll);
    } else if (line + electricScroll >= firstLine + visibleLines) {
      newFirstLine = (line - visibleLines) + electricScroll + 1;
      if (newFirstLine + visibleLines >= getLineCount())
        newFirstLine = getLineCount() - visibleLines;
      if (newFirstLine < 0)
        newFirstLine = 0;
    }

    int x = offsetToX(line, offset);
    int width = painter.getFontMetrics().charWidth('w');

    if (x < 0)
    {
      newHorizontalOffset = Math.min(0, horizontalOffset - x + width + 5);
    } else if (x + width >= painter.getWidth()) {
      newHorizontalOffset = horizontalOffset + (painter.getWidth() - x) - width - 5;
    }

    return setOrigin(newFirstLine, newHorizontalOffset);
  }
}

public class LINETOY {
/**
    * Converts a line index to a y co-ordinate.
    * @param line The line
    */
  public int lineToY(int line)
  {
    FontMetrics fm = painter.getFontMetrics();
    return (line - firstLine) * fm.getHeight() - (fm.getLeading() + fm.getMaxDescent());
  }
}

public class YTOLINE {
/**
    * Converts a y co-ordinate to a line index.
    * @param y The y co-ordinate
    */
  public int yToLine(int y)
  {
    FontMetrics fm = painter.getFontMetrics();
    int height = fm.getHeight();
    return Math.max(0, Math.min(getLineCount() - 1, y / height + firstLine));
  }
}

public class OFFSETTOX {
/**
    * Converts an offset in a line into an x co-ordinate.
    * @param line The line
    * @param offset The offset, from the start of the line
    */
  public int offsetToX(int line, int offset)
  {
    TokenMarker tokenMarker = getTokenMarker();

    /* Use painter's cached info for speed */
    FontMetrics fm = painter.getFontMetrics();

    getLineText(line, lineSegment);

    int segmentOffset = lineSegment.offset;
    int x = horizontalOffset;

    /* If syntax coloring is disabled, do simple translation */
    if (tokenMarker == null)
    {
      lineSegment.count = offset;
      return x + Utilities.getTabbedTextWidth(lineSegment, fm, x, painter, 0);
    }
    /* If syntax coloring is enabled, we have to do this because
      * tokens can vary in width */
    else
    {
      Token tokens = tokenMarker.markTokens(lineSegment, line);

      Toolkit toolkit = painter.getToolkit();
      Font defaultFont = painter.getFont();
      SyntaxStyle[] styles = painter.getStyles();

      for (;;)
      {
        byte id = tokens.id;
        if (id == Token.END)
        {
          return x;
        }

        if (id == Token.NULL)
          fm = painter.getFontMetrics();
        else
          fm = styles[id].getFontMetrics(defaultFont);

        int length = tokens.length;

        if (offset + segmentOffset < lineSegment.offset + length)
        {
          lineSegment.count = offset - (lineSegment.offset - segmentOffset);
          return x + Utilities.getTabbedTextWidth(lineSegment, fm, x, painter, 0);
        } else {
          lineSegment.count = length;
          x += Utilities.getTabbedTextWidth(lineSegment, fm, x, painter, 0);
          lineSegment.offset += length;
        }
        tokens = tokens.next;
      }
    }
  }
}

public class XTOOFFSET {
/**
    * Converts an x co-ordinate to an offset within a line.
    * @param line The line
    * @param x The x co-ordinate
    */
  public int xToOffset(int line, int x)
  {
    TokenMarker tokenMarker = getTokenMarker();

    /* Use painter's cached info for speed */
    FontMetrics fm = painter.getFontMetrics();

    getLineText(line, lineSegment);

    char[] segmentArray = lineSegment.array;
    int segmentOffset = lineSegment.offset;
    int segmentCount = lineSegment.count;

    int width = horizontalOffset;

    if (tokenMarker == null)
    {
      for (int i = 0; i < segmentCount; i++)
      {
        char c = segmentArray[i + segmentOffset];
        int charWidth;
        if (c == '\t')
          charWidth = (int) painter.nextTabStop(width, i) - width;
        else
          charWidth = fm.charWidth(c);

        if (painter.isBlockCaretEnabled())
        {
          if (x - charWidth <= width)
            return i;
        } else {
          if (x - charWidth / 2 <= width)
            return i;
        }

        width += charWidth;
      }

      return segmentCount;
    } else {
      Token tokens = tokenMarker.markTokens(lineSegment, line);

      int offset = 0;
      Toolkit toolkit = painter.getToolkit();
      Font defaultFont = painter.getFont();
      SyntaxStyle[] styles = painter.getStyles();

      for (;;)
      {
        byte id = tokens.id;
        if (id == Token.END)
          return offset;

        if (id == Token.NULL)
          fm = painter.getFontMetrics();
        else
          fm = styles[id].getFontMetrics(defaultFont);

        int length = tokens.length;

        for (int i = 0; i < length; i++)
        {
          char c = segmentArray[segmentOffset + offset + i];
          int charWidth;
          if (c == '\t')
            charWidth = (int) painter.nextTabStop(width, offset + i) - width;
          else
            charWidth = fm.charWidth(c);

          if (painter.isBlockCaretEnabled())
          {
            if (x - charWidth <= width)
              return offset + i;
          } else {
            if (x - charWidth / 2 <= width)
              return offset + i;
          }

          width += charWidth;
        }

        offset += length;
        tokens = tokens.next;
      }
    }
  }
}

public class XYTOOFFSET {
/**
    * Converts a point to an offset, from the start of the text.
    * @param x The x co-ordinate of the point
    * @param y The y co-ordinate of the point
    */
  public int xyToOffset(int x, int y)
  {
    int line = yToLine(y);
    int start = getLineStartOffset(line);
    return start + xToOffset(line, x);
  }
}

public class GETLINESTARTOFFSET {
/**
    * Returns the start offset of the specified line.
    * @param line The line
    * @return The start offset of the specified line, or -1 if the line is
    * invalid
    */
  public int getLineStartOffset(int line)
  {
    Element lineElement = document.getDefaultRootElement().getElement(line);
    if (lineElement == null)
      return -1;
    else
      return lineElement.getStartOffset();
  }
}

public class GETLINEENDOFFSET {
/**
    * Returns the end offset of the specified line.
    * @param line The line
    * @return The end offset of the specified line, or -1 if the line is
    * invalid.
    */
  public int getLineEndOffset(int line)
  {
    Element lineElement = document.getDefaultRootElement().getElement(line);
    if (lineElement == null)
      return -1;
    else
      return lineElement.getEndOffset();
  }
}

public class GETLINELENGTH {
/**
    * Returns the length of the specified line.
    * @param line The line
    */
  public int getLineLength(int line)
  {
    Element lineElement = document.getDefaultRootElement().getElement(line);
    if (lineElement == null)
      return -1;
    else
      return lineElement.getEndOffset() - lineElement.getStartOffset() - 1;
  }
}

public class GETSELECTIONSTART {
/**
    * Returns the offset where the selection starts on the specified
    * line.
    */
  public int getSelectionStart(int line)
  {
    if (line == selectionStartLine)
      return selectionStart;
    else if (rectSelect)
    {
      Element map = document.getDefaultRootElement();
      int start = selectionStart - map.getElement(selectionStartLine).getStartOffset();

      Element lineElement = map.getElement(line);
      int lineStart = lineElement.getStartOffset();
      int lineEnd = lineElement.getEndOffset() - 1;
      return Math.min(lineEnd, lineStart + start);
    } else
      return getLineStartOffset(line);
  }
}

public class GETSELECTIONEND {
/**
    * Returns the offset where the selection ends on the specified
    * line.
    */
  public int getSelectionEnd(int line)
  {
    if (line == selectionEndLine)
      return selectionEnd;
    else if (rectSelect)
    {
      Element map = document.getDefaultRootElement();
      int end = selectionEnd - map.getElement(selectionEndLine).getStartOffset();

      Element lineElement = map.getElement(line);
      int lineStart = lineElement.getStartOffset();
      int lineEnd = lineElement.getEndOffset() - 1;
      return Math.min(lineEnd, lineStart + end);
    } else
      return getLineEndOffset(line) - 1;
  }
}

public class NEXTTABSTOP {
/**
    * Implementation of TabExpander interface. Returns next tab stop after
    * a specified point.
    * @param x The x co-ordinate
    * @param tabOffset Ignored
    * @return The next tab stop after <i>x</i>
    */
  public float nextTabStop(float x, int tabOffset)
  {
    if (tabSize == 0)
    {
      tabSize = fm.charWidth(' ') *
              ((Integer) textArea.getDocument().getProperty(PlainDocument.tabSizeAttribute)).intValue();
    }

    int offset = textArea.getHorizontalOffset();
    int ntabs = ((int) x - offset) / tabSize;
    return (ntabs + 1) * tabSize + offset;
  }
}

public class ISVALIDFORCONSTRUCTOR {
/**
	 * Note: !isClassOrInterface(int mod) is assumed.
	 */
	public static boolean isValidForConstructor(int mod)
	{
		return ( (mod & INVALID_FOR_CONSTRUCTOR) == 0 ) ;
	}
}

public class HASHCODE {
/**
     * Returns a hash value based on a seed value and the value of a boolean
     * primitive.
     * 
     * @param pre  the seed value.
     * @param b  the boolean value.
     * 
     * @return A hash value.
     * 
     * @since 1.0.7
     */
    public static int hashCode(int pre, boolean b) {
        return 37 * pre + (b ? 0 : 1);
    }
}

public class HASHCODE {
/**
     * Returns a hash value based on a seed value and the value of an int
     * primitive.
     * 
     * @param pre  the seed value.
     * @param i  the int value.
     * 
     * @return A hash value.
     * 
     * @since 1.0.8
     */
    public static int hashCode(int pre, int i) {
        return 37 * pre + i;
    }
}

public class HASHCODE {
/**
     * Returns a hash value based on a seed value and the value of a double
     * primitive.
     * 
     * @param pre  the seed value.
     * @param d  the double value.
     * 
     * @return A hash value.
     * 
     * @since 1.0.7
     */
    public static int hashCode(int pre, double d) {
        long l = Double.doubleToLongBits(d);
        return 37 * pre + (int) (l ^ (l >>> 32));
    }
}

