public class GETX {
/**
	 * Gets the value of x on the specified layer
	 * @param layer the layer to obtain x for
	 * @return the value of x on the specified layer
	 */
	public double getX(int layer) {
		if (isVertex()) {
			return x[0];
		} else if (isEdge()) {
			return x[layer - minRank - 1];
		}

		return 0.0;
	}
}

