public class OFFSET {
/**
	 * 
	 * @param p1
	 * @param p2
	 * @param a1
	 * @param a2
	 * @param b1
	 * @param b2
	 * @return Returns the actual offset
	 */
	protected double offset(double p1, double p2, double a1, double a2,
			double b1, double b2) {
		double d, s, t;

		if (b1 <= p1 || p1 + a1 <= 0) {
			return 0.0;
		}

		t = b1 * a2 - a1 * b2;
		if (t > 0.0) {
			if (p1 < 0.0) {
				s = p1 * a2;
				d = s / a1 - p2;
			} else if (p1 > 0.0) {
				s = p1 * b2;
				d = s / b1 - p2;
			} else {
				d = -p2;
			}
		} else if (b1 < p1 + a1) {
			s = (b1 - p1) * a2;
			d = b2 - (p2 + s / a1);
		} else if (b1 > p1 + a1) {
			s = (a1 + p1) * b2;
			d = s / b1 - (p2 + a2);
		} else {
			d = b2 - (p2 + a2);
		}

		if (d > 0.0) {
			return d;
		} else {
			return 0.0;
		}
	}
}

