public class COMPUTEWINDOWSCALE {
/**
	 * Computes the scale for the window autoscale policy.
	 * 
	 * @param border
	 *            The border to use.
	 * @return Returns the scale to use for the graph.
	 */
	protected double computeWindowScale(int border) {
		Dimension size = getViewport().getExtentSize();
		Rectangle2D p = getGraph().getCellBounds(getGraph().getRoots());
		if (p != null) {
			return Math.min((double) size.getWidth()
					/ (p.getX() + p.getWidth() + border), (double) size
					.getHeight()
					/ (p.getY() + p.getHeight() + border));
		}
		return 0;
	}
}

public class COMPUTEPAGEWIDTHSCALE {
/**
	 * Computes the scale for the pagewidth autoscale policy.
	 * 
	 * @param border
	 *            The border to use.
	 * @return Returns the scale to use for the graph.
	 */
	protected double computePageWidthScale(int border) {
		Dimension size = getViewport().getExtentSize();
		Dimension p = getGraph().getMinimumSize();
		if (p != null && (p.getWidth() != 0 || p.getHeight() != 0)) {
			size.width = size.width - border;
			return (double) size.getWidth() / (double) p.getWidth();
		}
		return 0;
	}
}

public class ISADDEDCELL {
/**
	 * Returns true if the cell identified by <code>index</code> was added to
	 * the selection. A return value of false means the cell was in the
	 * selection but is no longer in the selection. This will raise an exception
	 * if index < 0 || >=<code>getPaths</code> .length.
	 * 
	 * @param index
	 *            the index of <code>areNew</code> of the cell that is to be
	 *            indicated as newly selected or not
	 * @return whether or not the cell is newly selected or not
	 */
	public boolean isAddedCell(int index) {
		if (cells == null || index < 0 || index >= cells.length) {
			throw new IllegalArgumentException(
					"index is beyond range of added cells identified by GraphSelectionEvent");
		}
		return areNew[index];
	}
}

