     * @return .
     */
    public int getMaxDuration(int methodNumber) {

        Long currentMax = null;
        int  max = 0;

        for (int i = 0; i < getSampleCount(); i++) {

            currentMax = getAccumulator(i, methodNumber).getMaxDuration();

            if (currentMax != null) {

                max = Math.max(max, currentMax.intValue());

            }

        }

        return max;

    }
}

