public class RECURSE {
/**
     * Method recurse
     *
     * @param x .
     *
     * @return .
     */
    private int recurse(int x)
    {
        if (x == 0)
        {
            return 0;
        }
        else
        {
            return x + (recurse(x - 1));
        }
    }
}

public class POSITIVERAND {
/**
     * Method positiveRand
     */
    private static long positiveRand(long max)
    {

        // System.out.println("max = " + max);
        return (Math.abs(random.nextLong()) % max);
    }
}

